class Solution {
public:
    string sortString(string s) {
        int cnt[26] = {0};
        for (char c : s) cnt[c - 'a']++;
        string res;
        res.reserve(s.size());
        int n = s.size();
        while ((int)res.size() < n) {
            for (int i = 0; i < 26; ++i) {
                if (cnt[i] > 0) {
                    res.push_back('a' + i);
                    --cnt[i];
                }
            }
            for (int i = 25; i >= 0; --i) {
                if (cnt[i] > 0) {
                    res.push_back('a' + i);
                    --cnt[i];
                }
            }
        }
        return res;
    }
};

code.java:
class Solution {
    public String sortString(String s) {
        int[] cnt = new int[26];
        for (char c : s.toCharArray()) {
            cnt[c - 'a']++;
        }
        StringBuilder res = new StringBuilder(s.length());
        int n = s.length();
        while (res.length() < n) {
            for (int i = 0; i < 26; i++) {
                if (cnt[i] > 0) {
                    res.append((char) ('a' + i));
                    cnt[i]--;
                }
            }
            for (int i = 25; i >= 0; i--) {
                if (cnt[i] > 0) {
                    res.append((char) ('a' + i));
                    cnt[i]--;
                }
            }
        }
        return res.toString();
    }
}

