/**
 * @param {string} s
 * @return {string}
 */
var sortString = function(s) {
    // Count frequency of each lowercase letter
    const cnt = new Array(26).fill(0);
    for (const ch of s) {
        cnt[ch.charCodeAt(0) - 97]++;
    }

    const res = [];
    const n = s.length;

    // Repeat until all characters are used
    while (res.length < n) {
        // Ascending pass: from 'a' to 'z'
        for (let i = 0; i < 26; i++) {
            if (cnt[i] > 0) {
                res.push(String.fromCharCode(97 + i));
                cnt[i]--;
            }
        }
        // Descending pass: from 'z' to 'a'
        for (let i = 25; i >= 0; i--) {
            if (cnt[i] > 0) {
                res.push(String.fromCharCode(97 + i));
                cnt[i]--;
            }
        }
    }

    return res.join('');
};
